<?php
require_once '/opt/hr/HrUi.php';require_once '/opt/hr/HrAuditSupport.php';
$bean=BeanFactory::newBean('HR_Audit');if(!$bean->ACLAccess('list')){http_response_code(403);die('Нет доступа к аудиту');}
$operations=['create'=>'Создание','update'=>'Изменение','delete'=>'Удаление','generate_document'=>'Генерация документа','save_document'=>'Сохранение документа','create_template'=>'Создание шаблона','save_template'=>'Сохранение шаблона','after_relationship_add'=>'Добавление связи','after_relationship_delete'=>'Удаление связи'];
$schema=require '/opt/hr/schema.php';$db=$GLOBALS['db'];
$filter=is_string($_GET['operation']??null)?$_GET['operation']:'';$module=is_string($_GET['module_filter']??null)?$_GET['module_filter']:'';$actor=is_string($_GET['actor']??null)?trim($_GET['actor']):'';$record=is_string($_GET['record']??null)?$_GET['record']:'';$offset=max(0,(int)($_GET['offset']??0));
$where=['deleted=0'];if(isset($operations[$filter]))$where[]='operation='.$db->quoted($filter);if(isset($schema[$module]))$where[]='entity_module='.$db->quoted($module);if($actor!=='')$where[]='actor_name='.$db->quoted($actor);if($record!=='')$where[]='entity_id='.$db->quoted($record);
$result=$db->limitQuery('SELECT * FROM hr_audit WHERE '.implode(' AND ',$where).' ORDER BY date_entered DESC,CASE WHEN JSON_VALID(description) THEN JSON_UNQUOTE(JSON_EXTRACT(description,"$._context.occurred_at")) ELSE "" END DESC,id DESC',$offset,21);$rows=[];while($row=$db->fetchByAssoc($result,false))$rows[]=$row;$more=count($rows)>20;$rows=array_slice($rows,0,20);
$labels=['assigned_user_id'=>'Ответственный','person_id'=>'Сотрудник','manager_id'=>'Руководитель','deleted'=>'Удалено','date_entered'=>'Дата создания','created_by'=>'Создал запись','relationship'=>'Связь','related_module'=>'Связанный раздел','related_id'=>'Связанная запись','related_name'=>'Название связанной записи','module'=>'Раздел','link'=>'Поле связи','revision'=>'Версия документа','template'=>'Шаблон','document'=>'Документ','source'=>'Исходный шаблон','title'=>'Название шаблона','contributors'=>'Участники редактирования'];
$params=['operation'=>$filter,'module_filter'=>$module,'actor'=>$actor,'record'=>$record];
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Аудит действий</title><?php hrUiStyle();?><body class="hr-page"><main class="hr-shell"><?php hrUiNav('audit');?><h1>История изменений</h1><p class="hr-muted">Кто, когда и какие данные изменил. Для изменений показаны значения до и после. <a href="<?=hrUiEscape(hrUiGuide('audit'))?>">Как читать журнал</a></p>
<form method="get" class="hr-panel"><input type="hidden" name="entryPoint" value="HrAudit"><div class="hr-form-grid"><label>Операция<select name="operation"><option value="">Все операции</option><?php foreach($operations as $key=>$label):?><option value="<?=hrUiEscape($key)?>" <?=$key===$filter?'selected':''?>><?=hrUiEscape($label)?></option><?php endforeach?></select></label><label>Раздел<select name="module_filter"><option value="">Все разделы</option><?php foreach($schema as $key=>$info):if($key==='HR_Audit')continue;?><option value="<?=hrUiEscape($key)?>" <?=$key===$module?'selected':''?>><?=hrUiEscape($info[0])?></option><?php endforeach?></select></label><label>Автор (логин)<input name="actor" value="<?=hrUiEscape($actor)?>" placeholder="Например, hr_editor"></label></div><?php if($record!==''):?><input type="hidden" name="record" value="<?=hrUiEscape($record)?>"><p class="hr-hint">Показана история выбранной записи.</p><?php endif?><div class="hr-actions"><button>Показать</button><a href="<?=hrUiEscape(hrUiUrl('HrAudit'))?>">Сбросить фильтры</a></div></form>
<?php foreach($rows as $row):$payload=hrAuditPayload($row['description']);$context=$payload['_context']??[];$eventName=$context['record_name']??preg_replace('/^'.preg_quote($row['operation'],'/').'\s+/u','',$row['name']);$at=(new DateTimeImmutable($row['date_entered'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(getenv('HR_TIMEZONE')?:'Europe/Moscow'));$author=$row['actor_name']?:'system';?>
<article class="hr-panel"><span class="hr-badge"><?=hrUiEscape($operations[$row['operation']]??$row['operation'])?></span><h3><?=hrUiEscape($eventName)?></h3><p><strong>Автор: <?=hrUiEscape($author)?></strong><?php if(!empty($context['actor_name'])):?> (<?=hrUiEscape($context['actor_name'])?>)<?php endif?> · <time datetime="<?=hrUiEscape($at->format(DATE_ATOM))?>"><?=hrUiEscape($at->format('d.m.Y H:i:s'))?></time> · <?=hrUiEscape($schema[$row['entity_module']][0]??$row['entity_module'])?></p>
<div class="hr-table-wrap"><table class="hr-table"><thead><tr><th>Поле / действие</th><th>Было</th><th><?=$row['operation']==='delete'?'Значение перед удалением':'Стало / значение'?></th></tr></thead><tbody>
<?php $shown=0;foreach($payload as $key=>$value):if(in_array($key,['_context','id','modified_user_id','template_hash','hash','actor_id'],true))continue;$shown++;$label=$schema[$row['entity_module']][1][$key][0]??$labels[$key]??$key;$diff=is_array($value)&&array_key_exists('before',$value)&&array_key_exists('after',$value);$before=$diff?$value['before']:null;$after=$diff?$value['after']:$value;$format=fn($v)=>is_scalar($v)&&isset($context['references'][$key][(string)$v])?$context['references'][$key][(string)$v]:hrAuditDisplayValue($key,$v);?><tr><th><?=hrUiEscape($label)?></th><td><?=hrUiEscape($format($before))?></td><td style="white-space:pre-wrap;overflow-wrap:anywhere"><?=hrUiEscape($format($after))?></td></tr><?php endforeach?>
<?php if(!$shown):?><tr><td colspan="3">У этого старого события нет сохранённых подробностей.</td></tr><?php endif?></tbody></table></div><p><a href="<?=hrUiEscape(hrUiUrl('HrAudit',['record'=>$row['entity_id']]))?>">Вся история этой записи</a></p><details><summary>Технические данные события</summary><p>ID записи: <?=hrUiEscape($row['entity_id'])?></p><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=hrUiEscape(json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))?></pre></details></article>
<?php endforeach?><?php if(!$rows):?><p class="hr-empty">События не найдены. Измените фильтры.</p><?php endif?><div class="hr-actions"><?php if($offset):?><a href="<?=hrUiEscape(hrUiUrl('HrAudit',$params+['offset'=>max(0,$offset-20)]))?>">Предыдущие</a><?php endif?><?php if($more):?><a href="<?=hrUiEscape(hrUiUrl('HrAudit',$params+['offset'=>$offset+20]))?>">Следующие</a><?php endif?></div></main></body></html>
